// Import the synthetic export generated by tools/generate_synthetic.py.
let
 Source=Csv.Document(File.Contents(pDataRoot & "/weekly_compliance.csv"),[Delimiter=",",Encoding=65001,QuoteStyle=QuoteStyle.Csv]),
 Headers=Table.PromoteHeaders(Source,[PromoteAllScalars=true]),
 Typed=Table.TransformColumnTypes(Headers,{{"load_id",type text},{"carrier",type text},{"lane",type text},
 {"week_start",type date},{"geofence_failure",Int64.Type},{"ping_failure",Int64.Type},
 {"excluded_no_movement",Int64.Type},{"failure_category",type text}})
in Typed
